<template>
  <div class="order-record">
    <title-line :title="title" />
    <div class="gameContent">
      <div v-if="!type" class="filter">
        <div class="filter-box" @click="showPop=!showPop">
          <div class="text">{{ dateList.find(item=>item.value===currentValue).name }}</div>
          <div class="drow_icon" />
        </div>
        <div v-if="showPop" class="typePop">
          <div v-for="item in dateList" :key="item.value" class="filterBox" @click="currentValue=item.value;showPop=false;onRefresh()">
            <div class="text">{{ item.name }}</div>
          </div>
        </div>
      </div>
      <!-- <div class="kinds">
        <div class="day">近30天</div>
      </div> -->
      <div class="totalData">
        <div v-for="(item,index) in totalData" :key="index" class="cell">
          <div class="data" :style="index===2&&item.value>0?'color:#56ae85':index===2&&item.value<0?'color:#fe4854':''">{{ item.value }}<span v-if="index===0">{{ $t('tzjl.tzjl03') }}</span></div>
          <div class="label">{{ item.label }}</div>
        </div>
        <!-- <div v-for="(item,index) in totalData" :key="index" class="item" :style="index===1?'width:40%;text-align: center;':''">
          {{ item.label }}
          <span :style="index===2&&item.value>0?'color:#56ae85':index===2&&item.value<0?'color:#fe4854':''">{{ item.value }}</span>
        </div> -->
      </div>
      <div class="detailList">

        <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
          <van-list
            v-model="loading"
            :finished="finished"
            :loading-text="$t('tzjl.tzjl50')"
            finished-text=""
            @load="onLoad"
          >
            <is-empty v-if="recordList.length===0" />
            <div v-for="(item,index) in recordList" :key="index" class="list-box">
              <div v-for="(ele,j) in item" :key="j" class="detail">
                <span>{{ ele.label }}</span>
                <div v-if="ele.label==='开奖号码'" class="openNum">
                  <div v-for="(obj,k) in ele.value.split('') " :key="k" :class="'dice'+obj" />
                </div>
                <div v-else-if="ele.label==='开奖号'" class="openNum">
                  <!-- <div v-for="(obj,k) in ele.value.split('') " :key="k" :class="'dice'+obj" /> -->
                  <div v-if="ele.value.split(',')[0]" class="open-info">
                    <div class="open">{{ ele.value.split(',')[0] }}</div>+
                    <div class="open">{{ ele.value.split(',')[1] }}</div>+
                    <div class="open">{{ ele.value.split(',')[2] }}</div>=
                    <div class="open">{{ ele.value.split(',')[3] }}</div>
                  </div>
                </div>
                <span v-else-if="ele.label===$t('tzjl.tzjl18')||ele.label===$t('tzjl.tzjl40')||ele.label===$t('tzjl.tzjl35')||ele.label===$t('tzjl.tzjl22')||ele.label===$t('tzjl.tzjl25')||ele.label===$t('tzjl.tzjl29')||ele.label===$t('tzjl.tzjl36')">{{ ele.value }}</span>
                <span v-else-if="ele.label===$t('tzjl.tzjl39')" :class="ele.value.includes('-')?'red': 'green'">{{ ele.value }}</span>
                <span v-else-if="ele.label===$t('tzjl.tzjl23')&&(ele.value==='中奖'||ele.value==='待开奖')" class="green">{{ ele.value }}</span>
                <span v-else-if="ele.label===$t('tzjl.tzjl23')&&ele.value==='未中奖'" class="red">{{ ele.value }}</span>
                <span v-else-if="ele.label===$t('tzjl.tzjl24')||ele.label===$t('tzjl.tzjl37')" class="yellow">{{ ele.value }}</span>
                <!-- <span v-else-if="ele.label==='钱包地址'" class="">{{ ele.showValue }}</span> -->
                <div v-else class="Period">
                  <span v-if="ele.label===$t('tzjl.tzjl28')||ele.label===$t('tzjl.tzjl27')">{{ ele.showValue }}</span>
                  <span v-else>{{ ele.value }}</span>
                  <div class="copy-icon" @click="doCopy(ele.value)" />
                  <span v-if="ele.label===$t('tzjl.tzjl28')" class="verify" @click="goVerify(item.find(obj=>obj.label===$t('tzjl.tzjl26')).value)">{{ $t('tzjl.tzjl30') }}</span>
                </div>
              </div>
            </div>
          </van-list>
        </van-pull-refresh>
      </div>
    </div>
  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { buyrecord, buyrecordAll } from '@/api/game'
export default {
  components: {
    TitleLine
  },
  // props: {
  //   type: {
  //     type: String,
  //     default: ''
  //   }
  // },
  data() {
    return {
      type: '',
      title: this.$t('tzjl.tzjl13'),
      totalData: [
        { label: this.$t('tzjl.tzjl14'), value: '' }, { label: this.$t('tzjl.tzjl15'), value: '' }, { label: this.$t('tzjl.tzjl16'), value: '' }
      ],
      recordList: [
        // [{ label: '注单编号', value: '12345' }], [{ label: '注单编号', value: '12345' }]
      ],
      showPop: false,
      currentValue: '1',
      dateList: [{ name: this.$t('wdsr.wdsr44'), value: '1' }, { name: this.$t('wdsr.wdsr45'), value: '2' }
      // , { name: '近7天', value: '7' }, { name: '近30天', value: '30' }
      ],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  mounted() {
    const type = this.$route.query.type
    this.type = type
    this.currentValue = this.$route.query.currentData
  },
  methods: {
    onLoad() {
      const type = this.$route.query.type
      if (type) {
        buyrecord({ type, pages: this.pageNum }).then(res => {
          this.totalData = res.totalData
          // this.recordList = res.recordList
          if (this.refreshing) {
            this.recordList = []
            this.refreshing = false
          }
          this.recordList = this.recordList.concat(res.recordList)
          this.loading = false
          this.pageNum++
          if (this.recordList.length >= Number(res.allnums)) {
            this.finished = true
          }
        })
      } else {
        buyrecordAll({ type: this.currentValue, gametype: this.$route.query.bigType, pages: this.pageNum }).then(res => {
          this.totalData = res.totalData
          // this.recordList = res.recordList
          if (this.refreshing) {
            this.recordList = []
            this.refreshing = false
          }
          this.recordList = this.recordList.concat(res.recordList)
          this.loading = false
          this.pageNum++
          if (this.recordList.length >= Number(res.allnums)) {
            this.finished = true
          }
        })
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    },
    goVerify(val) {
      // window.open('https://tronscan.org/#/block/' + val)
      this.$router.push({
        path: '/verifyIndex',
        query: {
          block: val,
          blockurl: ''
        }
      })
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
  }
}
</script>
